"use client";

import Image from "next/image";
import { useLayoutEffect, useRef, useState } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

const CARDS = [
  {
    number: "01",
    heading: "LinkedIn Content & Authority",
    headingLines: ["LinkedIn Content &", "Authority"],
    description:
      "Buyers check your LinkedIn before they answer your message. We build the presence that makes the reply easy, posted in your voice, every single week.",
    points: [
      {
        label: "LinkedIn Content & Posting",
        detail: "Posts and carousels, run end to end",
      },
      {
        label: "Profile & Positioning",
        detail: "The profile they land on after the post",
      },
      {
        label: "Newsletter & Content Hub",
        detail: "An owned audience that compounds",
      },
    ],
    color: "172,64,255",
  },
  {
    number: "02",
    heading: "LinkedIn Outreach",
    headingLines: ["LinkedIn", "Outreach"],
    description:
      "This is the heart of it. Managed LinkedIn DMs at real scale, sent by real people having real conversations. Calls and email wrap around the LinkedIn motion to back it up.",
    points: [
      {
        label: "LinkedIn DM Outreach",
        detail: "The primary channel, run at scale",
      },
      { label: "Cold Calling", detail: "Live voice on accounts that engage" },
      {
        label: "Email Marketing",
        detail: "The follow-up layer around LinkedIn",
      },
    ],
    color: "210,210,210",
  },
  {
    number: "03",
    heading: "Pipeline & Reporting",
    headingLines: ["Pipeline &", "Reporting"],
    description:
      "Attention is worthless until it books. We turn conversations into qualified calls and show you every number behind it.",
    points: [
      { label: "Lead Magnets & Funnels", detail: "A reason to raise a hand" },
      {
        label: "Appointment Setting",
        detail: "Booked calls, not just interest",
      },
      {
        label: "Pipeline Dashboard",
        detail: "Reach, replies and conversions, monthly",
      },
    ],
    color: "210,210,210",
  },
];

// The three fan-out slots the cards cycle through: front (centered, on top),
// mid (behind, offset left), back (behind, offset right and lower). Offsets
// are percentages of the card's own size (matching the Figma fan exactly),
// so the fan holds at any viewport.
const SLOTS = [
  { xPercent: 0, yPercent: 0, rotate: 0, zIndex: 3 },
  { xPercent: -17.9, yPercent: 18.6, rotate: -5, zIndex: 2 },
  { xPercent: 23.1, yPercent: 28.4, rotate: 5, zIndex: 1 },
];

// "The LinkedIn Growth Engine" is split char by char so it can be coupled
// to its first letter and pulled apart outward, the same entrance used by
// Hero's "This is a movement" line. Spaces are kept as real text nodes
// between word-groups (not char-spans) so they don't collapse to zero
// width — an inline-block span containing only a space renders empty.
function EyebrowChars({ text }) {
  const words = text.split(" ");
  const nodes = [];

  words.forEach((word, wi) => {
    nodes.push(
      <span key={`w-${wi}`} className="inline-block whitespace-nowrap">
        {word.split("").map((char, ci) => (
          <span key={ci} className="sprout-char inline-block opacity-0">
            {char}
          </span>
        ))}
      </span>,
    );
    if (wi < words.length - 1) nodes.push(" ");
  });

  return nodes;
}

// Splits on words, keeping spaces as real text nodes between them (so
// wrapping stays natural), and each word into individually animatable,
// opacity-only characters — the typewriter treatment used across the site.
function TypewriterChars({ text }) {
  const words = text.split(" ");
  const nodes = [];

  words.forEach((word, wi) => {
    nodes.push(
      <span key={`w-${wi}`} className="inline-block whitespace-nowrap">
        {word.split("").map((char, ci) => (
          <span key={ci} className="typewriter-char inline-block opacity-0">
            {char}
          </span>
        ))}
      </span>,
    );
    if (wi < words.length - 1) nodes.push(" ");
  });

  return nodes;
}

// The back slot has nothing behind it to blur, and reads as a flat, fully
// opaque card per the Figma design — but backdrop-blur-[5.5px] stays on
// every card regardless of slot (rather than being toggled by `isBack`) so
// there's no discrete class swap to pop when a card's slot changes: at full
// opacity the blur has no visible effect, so the back slot still renders
// flat, and when the shuffle animates a card's alpha down to 0.9 for the
// front/mid slots the blur is already there to fade in smoothly with it.
// See `handleAdvance` below, which tweens this same backgroundColor value
// in lockstep with the position/rotation so the two never fall out of sync
// mid-transition.
//
// `measure` renders the same content unconstrained (no `inset-0`, height
// auto) and hidden, so its rendered height reveals how tall this card's
// content actually needs to be at the current width — used to size the
// card stack, see the effect below that sets `cardHeight`.
function GrowthCard({ card, slotIndex, setCardRef, onAdvance, measure }) {
  const isBack = slotIndex === 2;

  return (
    <button
      type="button"
      ref={setCardRef}
      onClick={measure ? undefined : onAdvance}
      tabIndex={measure ? -1 : undefined}
      aria-hidden={measure || undefined}
      aria-label={
        measure ? undefined : `Bring ${card.heading} to the front`
      }
      className={`flex cursor-pointer flex-col overflow-hidden rounded-[clamp(14px,1.7361vw,25px)] px-[clamp(20px,2.5694vw,37px)] py-[clamp(18px,2.4306vw,35px)] text-left backdrop-blur-[5.5px] ${measure ? "invisible pointer-events-none absolute top-0 left-0 h-auto w-full" : "absolute inset-0"}`}
      style={{
        backgroundColor: `rgba(${card.color},${isBack ? 1 : 0.9})`,
      }}
    >
      <h3 className="max-w-[75%] font-anton-sc text-[clamp(20px,2.4306vw,35px)] uppercase leading-[1.05] text-[#101010]">
        {card.headingLines.map((line, index) => (
          <span key={index} className="block">
            {line}
          </span>
        ))}
      </h3>
      <p className="mt-[clamp(2px,0.2778vw,4px)] max-w-[85%] font-poppins text-[clamp(11px,0.8333vw,12px)] leading-[1.1] text-[#101010] sm:max-w-[65%]">
        {card.description}
      </p>

      <div className="mt-[clamp(3px,0.3472vw,5px)] w-[64%] border-t border-[#101010]/40" />

      <div className="mt-[clamp(20px,2.6389vw,38px)] flex items-end justify-between gap-4">
        <ul className="flex flex-col gap-[clamp(8px,0.9722vw,14px)]">
          {card.points.map((point) => (
            <li key={point.label} className="font-poppins text-[#101010]">
              <p className="text-[clamp(12px,1.1111vw,16px)] font-semibold uppercase leading-[1.15]">
                {point.label} -
              </p>
              <p className="text-[clamp(10px,0.8333vw,12px)] leading-[1.15]">
                {point.detail}
              </p>
            </li>
          ))}
        </ul>
        <span className="font-anton-sc text-[clamp(48px,6.9444vw,100px)] leading-none text-[#101010]">
          {card.number}
        </span>
      </div>
    </button>
  );
}

export default function GrowthEngineSection() {
  const [order, setOrder] = useState([0, 1, 2]);
  const [cardHeight, setCardHeight] = useState(null);
  const cardRefs = useRef([]);
  const measureRefs = useRef([]);
  const animatingRef = useRef(false);

  const sectionRef = useRef(null);
  const leftBranchRef = useRef(null);
  const rightBranchRef = useRef(null);
  const eyebrowRef = useRef(null);
  const headingRef = useRef(null);
  const descriptionRef = useRef(null);
  const cardsWrapperRef = useRef(null);
  const watermarkRef = useRef(null);

  useLayoutEffect(() => {
    order.forEach((cardIndex, slotIndex) => {
      const el = cardRefs.current[cardIndex];
      if (el) gsap.set(el, SLOTS[slotIndex]);
    });
  }, [order]);

  // The card stack's height is always measured from actual content rather
  // than held to a fixed aspect ratio. The card text uses `vw`-based
  // clamp() sizing, not container-query units, so how much height its
  // content needs doesn't scale linearly with card width — line-wrap
  // counts change in steps as the viewport grows, and clamp() maxes out
  // at wide viewports while the card keeps growing. A fixed aspect ratio
  // always ends up wrong somewhere: either it overflows the card (too
  // short) or leaves a dead gap below the content (too tall).
  useLayoutEffect(() => {
    let lastWidth = null;

    function recalc() {
      const width = cardsWrapperRef.current?.offsetWidth;
      // The wrapper's own height is set by this effect (below), so
      // observing it will re-fire on every height change too — skip
      // those and only recompute when the width actually moved, or a
      // ResizeObserver height feedback loop would just re-measure
      // against unchanged content and thrash without ever settling.
      if (width === lastWidth) return;
      lastWidth = width;

      const heights = measureRefs.current
        .filter(Boolean)
        .map((el) => el.offsetHeight);
      if (heights.length) setCardHeight(Math.max(...heights));
    }

    recalc();

    const ro = new ResizeObserver(recalc);
    if (cardsWrapperRef.current) ro.observe(cardsWrapperRef.current);
    window.addEventListener("resize", recalc);

    return () => {
      ro.disconnect();
      window.removeEventListener("resize", recalc);
    };
  }, []);

  // One-time entrance, played the moment the section reaches the viewport:
  // the tree branches slide in from left/right, the eyebrow line couples
  // to its first character and pulls apart like Hero's movement text, the
  // heading and description type on, and the card stack rises in from
  // below. Nothing here touches resting positions — every element ends up
  // exactly where its CSS already puts it.
  useLayoutEffect(() => {
    const eyebrowChars = [
      ...eyebrowRef.current.querySelectorAll(".sprout-char"),
    ];
    const headingChars = [
      ...headingRef.current.querySelectorAll(".typewriter-char"),
    ];
    const descriptionChars = [
      ...descriptionRef.current.querySelectorAll(".typewriter-char"),
    ];

    const ctx = gsap.context(() => {
      gsap.set(leftBranchRef.current, { xPercent: -50, opacity: 0 });
      gsap.set(rightBranchRef.current, { xPercent: 50, opacity: 0 });
      gsap.set(headingChars, { opacity: 0 });
      gsap.set(descriptionChars, { opacity: 0 });
      gsap.set(cardsWrapperRef.current, { y: 120, opacity: 0 });

      // Coupled to its first character — every other char and the bullet
      // start stacked on top of it, then pull apart outward, exactly like
      // Hero's "This is a movement" line.
      const anchorEl = eyebrowChars[0];
      const eyebrowEls = eyebrowChars;
      const anchorLeft = anchorEl.getBoundingClientRect().left;

      gsap.set(eyebrowEls, {
        opacity: 0,
        x: (_, target) => anchorLeft - target.getBoundingClientRect().left,
      });

      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: sectionRef.current,
          start: "top 75%",
          toggleActions: "play none none reverse",
        },
      });

      tl.to(
        [leftBranchRef.current, rightBranchRef.current],
        { xPercent: 0, opacity: 1, duration: 0.6, ease: "power3.out" },
        0,
      )
        .to(
          eyebrowEls,
          {
            x: 0,
            opacity: 1,
            duration: 0.3,
            ease: "power3.out",
            stagger: { each: 0.014, from: eyebrowEls.indexOf(anchorEl) },
          },
          "-=0.4",
        )
        .to(
          headingChars,
          { opacity: 1, duration: 0.01, stagger: 0.008, ease: "none" },
          "-=0.3",
        )
        .to(
          descriptionChars,
          { opacity: 1, duration: 0.01, stagger: 0.004, ease: "none" },
          "-=0.2",
        )
        .to(
          cardsWrapperRef.current,
          { y: 0, opacity: 1, duration: 0.5, ease: "power3.out" },
          "-=0.3",
        );
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  // The SPKRHED watermark sits far below the cards, past the section's own
  // entrance trigger, so it gets its own ScrollTrigger keyed to itself
  // rather than riding the section-wide timeline above.
  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      gsap.set(watermarkRef.current, { opacity: 0, y: 60 });

      gsap.to(watermarkRef.current, {
        opacity: 1,
        y: 0,
        duration: 1,
        ease: "power3.out",
        scrollTrigger: {
          trigger: watermarkRef.current,
          start: "top 90%",
          toggleActions: "play none none reverse",
        },
      });
    }, sectionRef);

    return () => ctx.revert();
  }, []);

  function handleAdvance() {
    if (animatingRef.current) return;
    animatingRef.current = true;

    const newOrder = [order[1], order[2], order[0]];
    const tl = gsap.timeline({
      onComplete: () => {
        setOrder(newOrder);
        animatingRef.current = false;
      },
    });

    newOrder.forEach((cardIndex, slotIndex) => {
      const el = cardRefs.current[cardIndex];
      if (!el) return;
      const isBack = slotIndex === 2;
      gsap.set(el, { zIndex: SLOTS[slotIndex].zIndex });
      tl.to(
        el,
        {
          xPercent: SLOTS[slotIndex].xPercent,
          yPercent: SLOTS[slotIndex].yPercent,
          rotate: SLOTS[slotIndex].rotate,
          backgroundColor: `rgba(${CARDS[cardIndex].color},${isBack ? 1 : 0.9})`,
          duration: 0.6,
          ease: "power2.inOut",
        },
        0,
      );
    });
  }

  return (
    <section
      ref={sectionRef}
      className="relative overflow-x-clip bg-[#0F0F0F] pt-[clamp(40px,4vw,58px)]"
    >
      {/* Fixed vw offset (not a % of the section's own height) so the vines'
          position never moves when unrelated content above them — like the
          eyebrow heading — changes size. A %-based top is relative to this
          section's total rendered height, so it silently drifts every time
          content height changes; vw is relative to the viewport only, and
          stays put. Each branch also fades both its top AND bottom edges
          out via a mask (rather than a black overlay div) so only the
          vine's pixels fade — the hero image behind it never gets
          darkened or smudged, and the overlap reads as one continuous
          vine instead of a hard-cropped rectangle. Same technique as
          PricingSection's tree branches. */}
      <div
        ref={leftBranchRef}
        className="pointer-events-none absolute top-[-19vw] left-[-25%] z-10 w-[50%] select-none"
      >
        <Image
          src="/images/Home/tree-branch-1.png"
          alt=""
          width={1615}
          height={2396}
          className="h-auto w-full max-w-none select-none rotate-80 -scale-x-100"
          style={{
            maskImage:
              "linear-gradient(to bottom, transparent, black 25%, black 70%, transparent)",
            WebkitMaskImage:
              "linear-gradient(to bottom, transparent, black 25%, black 70%, transparent)",
          }}
        />
      </div>
      <div
        ref={rightBranchRef}
        className="pointer-events-none absolute top-[-19vw] right-[-25%] z-10 w-[50%] select-none"
      >
        <Image
          src="/images/Home/tree-branch-1.png"
          alt=""
          width={1615}
          height={2396}
          className="h-auto w-full max-w-none select-none rotate-280"
          style={{
            maskImage:
              "linear-gradient(to bottom, transparent, black 25%, black 70%, transparent)",
            WebkitMaskImage:
              "linear-gradient(to bottom, transparent, black 25%, black 70%, transparent)",
          }}
        />
      </div>
      {/* z-20 keeps all the copy and cards above the z-10 vines, so the vines
          read as a background flourish behind the text instead of a graphic
          sitting on top of and obscuring it. */}
      <div className="relative z-20 mx-auto max-w-300 px-8 sm:px-12 lg:px-16">
        {/* whitespace-nowrap on the eyebrow forces it to stay a single line
            at any width — the vw-only clamp (no fixed px floor) scales the
            font down in lockstep with the viewport so it never overflows,
            rather than wrapping to a second line. Breaks out of the
            max-w-300 column (same mx-[calc(50%-50vw)] w-screen trick as
            WhyLinkedInSection's kicker) so the large text has the full
            viewport to scale into instead of overflowing past the
            column's edges at wide screens. */}
        <div className="mx-[calc(50%-50vw)] flex w-screen items-center justify-center gap-2 px-2 sm:gap-4">
          <span
            ref={eyebrowRef}
            className="whitespace-nowrap font-poppins text-[clamp(14px,6vw,130px)] font-bold uppercase text-white"
          >
            <EyebrowChars text="The LinkedIn Growth Engine" />
          </span>
        </div>

        <h2
          ref={headingRef}
          className="mx-auto mt-[clamp(32px,6vw,90px)] max-w-181.5 text-center font-anton-sc text-[clamp(32px,5vw,72px)] uppercase leading-none"
        >
          <span className="text-[#AC40FF]">
            <TypewriterChars text="LinkedIn at the center." />
          </span>{" "}
          <span className="text-white">
            <TypewriterChars text="Three parts, one motion." />
          </span>
        </h2>

        <p
          ref={descriptionRef}
          className="mx-auto mt-[clamp(16px,2.2222vw,32px)] max-w-204 text-center font-poppins text-[clamp(16px,1.3889vw,20px)] text-white"
        >
          <TypewriterChars text="Every client runs the same engine, and it lives on LinkedIn. Build the authority, start the conversations, convert them to calls. Cold calling and email wrap around it. Skip a part and you leave money on the table." />
        </p>

        <div
          ref={cardsWrapperRef}
          className="relative z-10 mx-auto mt-[clamp(56px,7.6389vw,110px)] mb-[clamp(140px,20.76vw,299px)] w-full max-w-165"
          style={{
            height: cardHeight ? `${cardHeight}px` : undefined,
          }}
        >
          {CARDS.map((card, index) => (
            <GrowthCard
              key={card.number}
              card={card}
              slotIndex={order.indexOf(index)}
              setCardRef={(el) => {
                cardRefs.current[index] = el;
              }}
              onAdvance={handleAdvance}
            />
          ))}
          {CARDS.map((card, index) => (
            <GrowthCard
              key={`measure-${card.number}`}
              card={card}
              slotIndex={0}
              measure
              setCardRef={(el) => {
                measureRefs.current[index] = el;
              }}
            />
          ))}
        </div>
      </div>

      <Image
        ref={watermarkRef}
        src="/images/services/growth-engine-watermark.svg"
        alt=""
        width={1441}
        height={235}
        className="pointer-events-none absolute inset-x-0 bottom-0 w-full select-none"
      />
    </section>
  );
}
