import Image from "next/image";

function CardBlock({ block }) {
  if (block.aside) {
    return (
      <p className="font-poppins text-[clamp(9px,0.8333vw,12px)] leading-snug lg:leading-tight italic text-white/70 uppercase">
        {block.aside}
      </p>
    );
  }

  return (
    <div>
      <p className="font-poppins text-[clamp(11px,1.0417vw,15px)] leading-snug lg:leading-tight font-bold text-white uppercase">
        {block.label}
      </p>
      <p className="mt-[clamp(6px,0.4167vw,6px)] font-poppins text-[clamp(9px,0.9028vw,13px)] leading-snug lg:leading-tight text-white/70 uppercase">
        {block.detail}
      </p>
    </div>
  );
}

const HEADING_COLOR = {
  purple: "text-[#ac40ff]",
  white: "text-white",
};

export default function EngineCard({
  card,
  cardRef,
  revealRef,
  variant = "back",
  className = "",
  style,
}) {
  const isBack = variant === "back";

  const maskStyle = {
    WebkitMaskImage: `url(${card.mask})`,
    maskImage: `url(${card.mask})`,
    WebkitMaskSize: "100% 100%",
    maskSize: "100% 100%",
    WebkitMaskRepeat: "no-repeat",
    maskRepeat: "no-repeat",
  };

  return (
    <div ref={cardRef} className={`absolute ${className}`} style={style}>
      {/*
        The mask lives on this decorative-only layer, never on the text
        below. The mask's SVG notch (top-right corner, cut via alpha) turns
        anything under it fully transparent past the shape's silhouette —
        fine for a background image, but it silently disappears real text
        that strays into that region (e.g. the eyebrow on narrow mobile
        widths, where the notch's cut-through zone starts as low as ~42%
        of the card's width). Keeping content outside the mask means a
        rendering surprise shows up as visible overflow, not invisible text.
      */}
      <div
        aria-hidden
        className="absolute inset-0 rounded-[clamp(18px,2.1875vw,32px)] backdrop-blur-[5.5px] transform-gpu"
        style={maskStyle}
      >
        <Image
          src={card.shape}
          alt=""
          fill
          unoptimized
          sizes="(min-width: 1024px) 83vw, 90vw"
          className={`pointer-events-none rounded-[clamp(18px,2.1875vw,32px)] select-none ${isBack ? "opacity-20" : "opacity-50"}`}
          style={{ objectFit: "fill" }}
        />
      </div>

      <div
        className={`relative flex h-full flex-col p-[clamp(26px,3.6111vw,52px)] ${isBack ? "opacity-35" : ""}`}
      >
        <p className="font-poppins text-[clamp(16px,2.2222vw,32px)] font-bold text-white lg:text-[clamp(20px,2.7778vw,40px)]">
          {card.eyebrow}
        </p>

        {/*
          The card's SVG mask cuts a diagonal notch out of the top-right
          corner (roughly the top 19% of height, right 58% of width — see
          foundation-card-mask.svg). A full-width heading's first line sits
          right in that band, so on mobile it needs enough top clearance to
          drop below the notch before going full-width; lg keeps the
          original 50%-width layout, which never reaches the notch.
        */}
        <h3 className="mt-16 lg:mt-[clamp(8px,1.25vw,18px)] lg:max-w-[50%] font-anton-sc text-[clamp(20px,2.7778vw,40px)] leading-[1.15] lg:leading-[1.02] uppercase">
          {card.headingLines.map((line, index) => (
            <span
              key={index}
              className={`block ${HEADING_COLOR[line.color]}`}
            >
              {line.text}
            </span>
          ))}
        </h3>

        <p className="mt-[clamp(12px,1.3194vw,19px)] max-w-full lg:max-w-[51.6%] font-poppins text-[clamp(10px,1.0417vw,15px)] leading-relaxed lg:leading-tight text-white uppercase">
          {card.body}
        </p>

        <div className="mt-auto grid grid-cols-2 gap-x-[clamp(24px,3.8889vw,56px)] pt-[clamp(16px,2.2222vw,32px)]">
          {card.columns.map((column, colIndex) => (
            <div
              key={colIndex}
              className="flex flex-col justify-end gap-[clamp(10px,1.25vw,18px)]"
            >
              {column.map((block, blockIndex) => (
                <CardBlock key={blockIndex} block={block} />
              ))}
            </div>
          ))}
        </div>
      </div>

      {/*
        Entrance and swap used to fade THIS card's own opacity (0 -> 1) via
        GSAP. Chromium doesn't recompute a descendant's backdrop-filter in
        sync with an ancestor's opacity tween — will-change/transform-gpu on
        the blurred layer above didn't fix it either — so the card would
        render with a sharp, unblurred background for the first frame or
        two and then visibly "pop" into blur once the opacity animation
        settled. This plain (non-backdrop-filtered) cover sits on top and
        is what actually gets faded instead: the card itself stays at a
        constant opacity 1 the whole time (already fully, correctly
        blurred from its very first paint), and revealing it is just this
        cover fading away. Solid bg-black to match the section's own
        background so it reads as "nothing there yet," not a visible flash
        of black.
      */}
      {revealRef && (
        <div
          ref={revealRef}
          aria-hidden
          className="pointer-events-none absolute inset-0 z-50 rounded-[clamp(18px,2.1875vw,32px)] bg-black"
        />
      )}
    </div>
  );
}
